/**
 * Maps a Commerce API product onto the props the PDP's static-information components take.
 *
 * Extracted from the page so the mapping is unit-testable on its own. Nothing else on the PDP
 * ties an external field name to a rendered prop, and a mis-keyed field here does not fail
 * loudly: it falls through to `undefined`, the component returns `null`, and the page renders
 * a plausible-looking product with one line quietly missing. Neither a Storybook `play`
 * (which supplies its own props) nor an axe run can see that.
 */

/*
 * The Commerce SDK's `Product` type does not carry Zimmermann's `c_*` custom attributes, and
 * `@salesforce/retail-react-app` ships no types at all. This is the narrow shape this mapping
 * actually reads — everything optional, because every one of these fields can be absent on a
 * real catalogue product.
 */
/**
 * Shape of `c_tabDescription`/`c_tabDetails` — a rich-text attribute authored with both a
 * rendered `markup` (HTML, same shape as `longDescription`) and its plain-text `source`. Only
 * `markup` is read below, matching how every other rich-text field on this page is consumed
 * (through `app/utils/richText`'s HTML parser, not the plain-text form).
 */
export type SfccRichTextAttribute = {
  markup?: string;
  source?: string;
};

export type PdpSourceProduct = {
  id?: string;
  name?: string;
  longDescription?: string;
  /** Master product reference. Present on a variant; absent on a standard product. */
  master?: { masterId?: string };
  /** Zimmermann custom attribute holding the model's measurements and worn size. */
  c_modelFit?: string;
  /** Zimmermann custom attribute holding the product's care instructions, authored in Business
   *  Manager with the same markup shape as `longDescription` (see `app/utils/richText`). */
  c_careInstructions?: string;
  /** Colour code (e.g. "GVSCP") — not a display name. */
  c_color?: string;
  c_colourId?: string;
  /** EU Environmental Qualities content — SFCC-266's data source (MuleSoft/AP21), not this
   *  page's own concern yet; mapped here so that tab has it ready when it's built. */
  c_environmentalNotes?: string;
  c_fabricComposition?: string;
  /** Customs/tariff Harmonized System code — not a PDP display field. */
  c_hsCode?: string;
  /** SFCC-102's Size & Fit content, if/when that tab moves off Contentful onto this attribute —
   *  see the plan doc's note that Size & Fit was assumed Contentful-managed; not wired into
   *  DetailsAndCareContent or the Size & Fit tab yet, pending that confirmation. */
  c_sizeFit?: string;
  c_styleId?: string;
  c_styleNumber?: string;
  c_stylingNotes?: string;
  c_tabDescription?: SfccRichTextAttribute;
  c_tabDetails?: SfccRichTextAttribute;
};

/** The subset of `getPriceData`'s result this mapping needs. */
export type PdpSourcePrice = {
  currentPrice?: number;
  /** True when the variant's selling price is below its list (RRP) price — PRC-09. */
  isOnSale?: boolean;
  /** The original RRP. Present when `isOnSale` is true. */
  listPrice?: number;
  /**
   * True when `currentPrice` is the minimum across a set of variants rather than a single
   * definite price — e.g. a colour-only selection where sizes have different sale prices.
   * When true, Was/Now is suppressed: `currentPrice` is not a settled figure and showing a
   * definite Was/Now would misrepresent the product's pricing.
   */
  isRange?: boolean;
};

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl. */
export type FormatPrice = (amount: number, currency: string) => string;

export type PdpProductInfo = {
  name: string;
  /** Active selling price (the "Now" price when on sale). */
  price: string;
  /** Original RRP. Present only when the product is on sale (PRC-09). */
  wasPrice?: string;
  description?: string;
  modelInfo?: string;
  careInstructions?: string;
  styleCode?: string;
  colour?: string;
  colourId?: string;
  environmentalNotes?: string;
  fabricComposition?: string;
  hsCode?: string;
  sizeFit?: string;
  styleId?: string;
  styleNumber?: string;
  stylingNotes?: string;
  tabDescription?: string;
  tabDetails?: string;
};

/**
 * @param product - The resolved product (variant when one is selected, master otherwise).
 * @param priceData - `getPriceData(...)`'s result, as ProductView computes it.
 * @param currency - The storefront's active currency code.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the static-information components, or `null` while the product loads.
 */
/** One item in the `c_relatedSwatches` array resolved by the SCAPI hook (SFCC-708). */
export type RelatedSwatch = {
  masterProductID: string;
  colourValue: string;
  displayName: string;
  swatchImageURL: string;
};

export const selectPdpProductInfo = (
  product: PdpSourceProduct | undefined | null,
  priceData: PdpSourcePrice | undefined | null,
  currency: string,
  formatPrice: FormatPrice,
): PdpProductInfo | null => {
  if (!product?.name) return null;

  return {
    name: product.name,
    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
    // PRC-09: expose the original RRP as wasPrice only when the item is genuinely on sale,
    // the price is a settled definite figure (not a range minimum), and the list price is a
    // real number. When `isRange` is true, `currentPrice` is the cheapest across a set of
    // variants — showing a definite Was/Now would misrepresent the price for other variants.
    // The Was/Now atoms branch on wasPrice's presence; when absent ZimmProductPrice renders
    // the standard single-price treatment.
    wasPrice:
      priceData?.isOnSale &&
      !priceData.isRange &&
      typeof priceData.currentPrice === 'number' &&
      typeof priceData.listPrice === 'number'
        ? formatPrice(priceData.listPrice, currency)
        : undefined,
    description: product.longDescription,
    modelInfo: product.c_modelFit,
    careInstructions: product.c_careInstructions,
    // The style code shoppers see is the *master* style number. `product.id` is the variant
    // SKU once a size is selected, so reading it would silently show a different value after
    // the first swatch click. Standard products have no master, and there `id` is correct.
    // Unchanged by the c_styleNumber addition below: Tim hasn't confirmed this should switch to
    // that attribute, only that c_styleNumber should be mapped and available.
    styleCode: product.master?.masterId ?? product.id,
    colour: product.c_color,
    colourId: product.c_colourId,
    environmentalNotes: product.c_environmentalNotes,
    fabricComposition: product.c_fabricComposition,
    hsCode: product.c_hsCode,
    sizeFit: product.c_sizeFit,
    styleId: product.c_styleId,
    styleNumber: product.c_styleNumber,
    stylingNotes: product.c_stylingNotes,
    tabDescription: product.c_tabDescription?.markup,
    tabDetails: product.c_tabDetails?.markup,
  };
};

/**
 * Maps SCAPI `c_relatedSwatches` items onto ZimmColourSwatchGroup-compatible swatch values.
 *
 * `urlBuilder` and `colourAttrId` are injected so this module stays dependency-free and
 * testable without a router context — the same pattern `selectPdpProductInfo` uses for
 * `formatPrice`.
 *
